// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    // fuzzed params: the min value to set and an attacker initial balance to enable reentrancy via payable fallback
    function testFuzz_property(uint256 newMin, uint256 attackerFunds) public {
        // keep funds reasonable to avoid overflows in test environment but leave wide
        attackerFunds = bound(attackerFunds, 0, 1 ether);

        // deploy attacker helper that will re-enter SetMinSum during the external call sequence
        attacker = new Attacker(address(c));

        // fund attacker so it can perform payable calls if needed
        if (attackerFunds > 0) {
            vm.deal(address(attacker), attackerFunds);
        }

        // The attacker will be used as msg.sender to call SetMinSum. It will attempt to re-enter and change MinSum
        // to a different value (we pick newMin + 1) during the first SetMinSum execution.

        // Perform the call via the attacker; capture whether the external call completed without revert
        bool ok;
        try attacker.doSetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): on the correct contract, after the call finishes, MinSum equals the requested value.
        // We assert that c.MinSum() == newMin. This holds for the reference (nonReentrant_ works), and will fail for the buggy mutant
        // when the attacker successfully re-enters and changes MinSum during the call.
        assertTrue(c.MinSum() == newMin);
    }
}

// Minimal attacker that re-enters C.SetMinSum by calling back in its fallback during the initial call.
// It calls SetMinSum on c; during that external call, because SetMinSum on the buggy contract does not lock,
// the fallback will be invoked and perform another SetMinSum to a different value (newMin + 1), altering state mid-call.
contract Attacker {
    address immutable target;
    uint256 reentrancyTargetValue;

    constructor(address _target) {
        target = _target;
    }

    // entry point called from test; forwards a call to c.SetMinSum with msg.sender = this contract
    function doSetMinSum(uint256 v) external {
        // store the alternative value we will set during reentry
        reentrancyTargetValue = v + 1;
        // call SetMinSum on target (this contract is msg.sender for C)
        C(target).SetMinSum{ }(v);
    }

    // fallback triggered if the target contract makes an external call to this contract during SetMinSum.
    // When triggered, attempt to re-enter SetMinSum to change MinSum to reentrancyTargetValue.
    fallback() external payable {
        // perform reentrant call to change MinSum to a different value
        // ignore failures to keep behavior robust across versions
        try C(target).SetMinSum(reentrancyTargetValue) {} catch {}
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: the value to set and an initial funding amount for the attacker
    function testFuzz_property(uint256 v, uint256 attackerFund) public {
        // keep attackerFund reasonable but wide
        attackerFund = bound(attackerFund, 0, 1 ether);

        // deploy an attacker that will reenter SetMinSum during the external call
        Attacker attacker = new Attacker(address(c));

        // fund attacker so it can perform calls that send ETH if needed
        vm.deal(address(attacker), attackerFund);

        // register the attacker's address as the LogFile so that when C calls LogFile.AddMessage
        // it will invoke the attacker's fallback/receive and attempt reentrancy.
        // We must call SetLogFile before Initialized, and both are protected by nonReentrant_ in the original.
        // First, set the LogFile to the attacker address.
        // Use vm.prank to act as some externally owned account
        address admin = address(0xABCD);
        vm.prank(admin);
        c.SetLogFile(address(attacker));

        // Now call SetMinSum(v) as admin; in the buggy contract the attacker can reenter during the LogFile.AddMessage
        // call and change MinSum, causing final MinSum != v. We observe c.MinSum() after the call.
        bool ok;
        vm.prank(admin);
        try c.SetMinSum(v) { ok = true; } catch { ok = false; }

        // The universal property we assert: on the correct contract, SetMinSum(v) completes (ok == true)
        // and the stored MinSum equals the requested v. We can only assert one boolean reading c, so assert that
        // MinSum equals v. This holds for the reference implementation for all inputs; the mutant allows
        // reentrancy and can make MinSum differ for some inputs, causing this assertion to fail.
        assertTrue(c.MinSum() == v);
    }
}

// Minimal attacker: implements the LogFile interface expected by C and reenters SetMinSum during AddMessage.
contract Attacker {
    address public target;
    bool public reentered;
    constructor(address _t) payable {
        target = _t;
        reentered = false;
    }

    // This function matches Log.AddMessage signature in C and will be called by C during Put/Collect/AddMessage flows.
    // Here we attempt a reentrant call to SetMinSum with a different value to disturb MinSum when nonReentrant_ is broken.
    function AddMessage(address, uint, string memory) public {
        // only attempt one reentry to avoid infinite recursion
        if (!reentered) {
            reentered = true;
            // try to set a different MinSum to create a divergence
            // pick a non-zero value distinct from 0 to maximize chance of differing from fuzzed v
            // but we must not hard-code the deciding v — this is just an adversarial action
            C(target).SetMinSum(1);
        }
    }
}

