pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: attacker initial deposit (to enable fallback reentrancy), and the intended min value
    function testFuzz_property(uint256 deposit, uint256 v) public {
        // keep deposit to a reasonable non-zero ether value and v wide
        deposit = bound(deposit, 1 wei, 1 ether);

        // deploy an attacker that will reenter SetMinSum during the SetMinSum call
        Attacker attacker = new Attacker(address(c));

        // fund attacker so it can call into c and be used as msg.sender in Put via fallback
        vm.deal(address(attacker), deposit);

        // Configure attacker to try to reenter SetMinSum with a different value (v ^ 1)
        uint256 reenterValue = v ^ 1; // fuzzed-dependent different value
        attacker.configure(address(this), reenterValue);

        // The attack path: we need the contract's fallback to call Put which logs via LogFile.
        // To trigger reentrancy via SetMinSum, attacker will call SetLogFile pointing to attacker so that
        // during Put the attacker fallback is executed and reenters SetMinSum if the modifier is no-op.

        // Set the LogFile to attacker (attacker implements AddMessage signature)
        // Use vm.prank to be the caller for these admin actions
        vm.prank(address(this));
        c.SetLogFile(address(attacker));

        // ensure c not initialized so SetMinSum can be called
        vm.prank(address(this));
        // call SetMinSum from this contract; attacker will, during fallback invoked by Put, attempt reentry
        // First, have attacker deposit by calling fallback (call to c with value triggers Put via fallback)
        // Attacker will call c (payable) to cause Put and during Put the LogFile (attacker) will be called
        // which will trigger attacker fallback to reenter SetMinSum if allowed.

        // Attacker performs a payable call to c causing Put and the attack during the logging call
        attacker.attack{value: deposit}();

        // Now call SetMinSum normally to set to v
        vm.prank(address(this));
        bool ok;
        try c.SetMinSum(v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general invariant: for the correct contract, after SetMinSum(v) completes, MinSum == v
        // (we assert this via the public getter). The buggy contract with removed lock can be reentered
        // by attacker during the call and change MinSum, making MinSum != v for some inputs.
        assertTrue(c.MinSum() == v || !ok == false);
        // NOTE: The single assert reads c.MinSum(); it will always be equal to v on the reference contract.
        // On the mutant (no lock), the attacker reentering during logging can change MinSum so this assertion can fail.
    }
}

// Minimal attacker that will act as LogFile and reenter SetMinSum when AddMessage is called
contract Attacker {
    address public target;
    address public owner;
    uint256 public reenterValue;

    constructor(address _t) {
        target = _t;
        owner = msg.sender;
    }

    function configure(address _owner, uint256 _v) external {
        require(msg.sender == owner || msg.sender == address(this) || owner == address(0));
        owner = _owner;
        reenterValue = _v;
    }

    // function matching Log.AddMessage signature
    function AddMessage(address, uint, string memory) public {
        // reenter SetMinSum on target
        // ignore success/failure
        (bool s, ) = target.call(abi.encodeWithSignature("SetMinSum(uint256)", reenterValue));
        s;
    }

    // helper to initiate the attack by sending ETH to target which triggers fallback -> Put -> LogFile.AddMessage
    function attack() external payable {
        // call target so its fallback triggers Put and then calls LogFile (this)
        (bool s, ) = target.call{value: msg.value}("");
        s;
    }
}

