pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: the candidate MinSum value and an initial deposit amount
    // The attacker contract will be deployed inside the test and used as the LogFile
    function testFuzz_property(uint256 newMin, uint256 deposit) public {
        // keep domains wide but sensible (avoid trivial zero-deposit unless useful)
        deposit = bound(deposit, 0, 1 ether);

        // Deploy attacker that will try to reenter SetMinSum during Log.AddMessage
        Attacker attacker = new Attacker(address(c));

        // initialize: set the LogFile to the attacker so that calls to LogFile.AddMessage go to attacker
        // The SetLogFile call must succeed; no reentrancy should be possible on the correct contract
        // We call SetLogFile with the attacker's address
        c.SetLogFile(address(attacker));

        // Now attempt to call SetMinSum while attacker is in place. The attacker, when receiving
        // the AddMessage call, will attempt to reenter SetMinSum with a different value.
        // We fuzz newMin; the attacker will try to set it to newMin ^ 0xdead to create a detectable change.

        // Make the call from an EOA
        address caller = address(0xBEEF);
        vm.prank(caller);
        // Call SetMinSum; capture success via try/catch in case mutant behaves differently
        bool ok;
        try c.SetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single universal assertion: on the correct contract, after SetMinSum(newMin) completes successfully,
        // MinSum must equal exactly newMin. The mutant (no-op nonReentrant_) can be re-entered by attacker
        // during the LogFile.AddMessage call triggered by Put/Collect/SetLogFile/SetMinSum sequence and may
        // change MinSum so that MinSum != newMin for some fuzzed inputs. We assert the property only when the
        // SetMinSum call returned ok (i.e., completed) to observe final state.
        if (ok) {
            assertTrue(c.MinSum() == newMin);
        } else {
            // If the call reverted on reference, it must revert for all inputs — but to be safe we still assert true
            // on a revert path by checking that MinSum is not left in an unexpected different value is not possible here.
            // We simply assert that the call did not succeed implies the final MinSum is unchanged from 0 (initial).
            // The reference contract's SetMinSum only reverts if already initialized; in our test it's not initialized.
            // This branch should not be hit on reference; keep it permissive.
            assertTrue(c.MinSum() == 0);
        }
    }
}

// Attacker contract: used as the LogFile. When AddMessage is called, it will attempt to reenter
// SetMinSum on the target contract to change MinSum during the outer SetMinSum call if reentrancy is possible.
contract Attacker {
    C target;
    bool reentered;

    constructor(address _c) {
        target = C(_c);
        reentered = false;
    }

    // mimic the Log.AddMessage signature
    function AddMessage(address, uint, string memory) public {
        // attempt to reenter only once to avoid infinite recursion
        if (!reentered) {
            reentered = true;
            // choose a value different from caller-supplied one; deterministic tweak
            uint256 attackerVal = 0xDEADBEEF;
            // try to reenter SetMinSum; ignore failures
            try target.SetMinSum(attackerVal) {
            } catch {
            }
        }
    }
}

