pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: attacker will be given control to be set as LogFile, and newMin is the value to set
    function testFuzz_property(address attackerAddr, uint256 newMin) public {
        // keep attackerAddr non-zero to be a deployed contract below; allow fuzzer to pick arbitrary
        vm.assume(attackerAddr != address(0));

        // deploy a malicious Log that will reenter SetMinSum when AddMessage is called
        MaliciousLog mal = new MaliciousLog(address(c));

        // register malicious log in contract c
        // SetLogFile can only be called once before Initialized; it is protected by nonReentrant_ in reference
        // but calling it here should succeed in both reference and mutant
        c.SetLogFile(address(mal));

        // Now call SetMinSum under a prank from attackerAddr (to simulate arbitrary caller)
        vm.prank(attackerAddr);

        // Try/catch to ensure we observe call success/failure; the reference does not revert
        bool ok;
        try c.SetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        // single assertion: on the correct contract, SetMinSum completes successfully and MinSum equals newMin
        // Read MinSum via public getter
        assertTrue(ok && c.MinSum() == newMin);
    }
}

// Malicious Log that on AddMessage will attempt to reenter SetMinSum to change MinSum to a different value
contract MaliciousLog {
    address public target;
    bool public firstCall;

    constructor(address _t) {
        target = _t;
        firstCall = true;
    }

    // matching signature AddMessage(address,uint,string)
    function AddMessage(address, uint, string memory) public {
        // On first invocation, reenter SetMinSum to change MinSum to some other value (e.g., 1)
        if (firstCall) {
            firstCall = false;
            // attempt to reenter SetMinSum; ignore success/failure
            // call with a different value (1) to try to change MinSum during the original SetMinSum
            // use low-level call to avoid propagation of revert to caller
            (bool s, ) = target.call(abi.encodeWithSignature("SetMinSum(uint256)", 1));
            s; // silence unused
        }
    }
}

