pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: actor (attacker) and two candidate values for MinSum
    function testFuzz_property(address attacker, uint256 v1, uint256 v2) public {
        vm.assume(attacker != address(0));
        // keep values wide but bounded to avoid overflow in helper
        v1 = bound(v1, 1, type(uint256).max - 1);
        v2 = bound(v2, 1, type(uint256).max - 1);
        // Deploy adversarial attacker that will re-enter SetMinSum during SetMinSum call
        ReentrantAtt a = new ReentrantAtt(c);

        // Fund attacker so it can send txs if needed
        vm.deal(address(a), 1 ether);

        // First, make sure the contract is in uninitialized state (it is by default)
        // The general rule: a single external call to SetMinSum cannot be re-entered to change MinSum mid-execution.
        // We check by having the attacker call SetMinSum(v1) while its fallback re-enters SetMinSum(v2).
        // With correct nonReentrant_ this second entry will revert/abort and MinSum stays as v1.
        // With the bug (require removed), the reentrant call will succeed and overwrite MinSum to v2.

        // Set the attacker to request v2 during reentry
        a.setTargetValues(v1, v2);

        // Make the call from the attacker contract so its fallback can re-enter
        // Use vm.prank to set msg.sender to the attacker contract address
        vm.prank(address(a));
        // call SetMinSum on c; capture whether it completed without bubbling an external revert
        bool ok;
        try c.SetMinSum(v1) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion reading c: The correct contract always results in MinSum == v1 after this operation
        // (reentrant attempt fails or is prevented), while the buggy contract (without require) allows MinSum == v2
        // for some inputs (the fuzzer will find such inputs). We assert that MinSum equals v1.
        // Note: this assertion is satisfied by the reference for all inputs; it will fail on the mutant
        // when reentrancy is possible and the reentrant SetMinSum(v2) overwrites it.
        assertTrue(c.MinSum() == v1);
    }
}

// Minimal re-entrant attacker: during its call to c.SetMinSum, its fallback will re-enter c.SetMinSum with v2
contract ReentrantAtt {
    C target;
    uint256 public re1;
    uint256 public re2;
    bool public entered;

    constructor(C _t) {
        target = _t;
        entered = false;
    }

    function setTargetValues(uint256 _v1, uint256 _v2) public {
        re1 = _v1;
        re2 = _v2;
    }

    // When this contract calls target.SetMinSum(re1), the fallback will be triggered by the target during any external call
    // to this contract; to ensure fallback runs during the call, we make no external calls that send value here.
    // We initiate the call from this contract (in the test via vm.prank(address(a)); c.SetMinSum(v1)).

    fallback() external payable {
        // re-enter only once to avoid infinite recursion
        if (!entered) {
            entered = true;
            // attempt to re-enter and overwrite MinSum
            // ignore revert if it happens
            try target.SetMinSum(re2) {
            } catch {
            }
        }
    }
}

