// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: the new minimum value to set, and a boolean that decides whether the adversarial
    // Log contract will attempt a reentrant call during the first SetMinSum.
    function testFuzz_property(uint256 newVal, bool attackerWillReenter) public {
        // keep domain wide
        // deploy adversarial log that may reenter into c during SetMinSum
        ReentrantLog attacker = new ReentrantLog(address(c));

        // register the log contract address in c
        // SetLogFile is protected by nonReentrant_ as well; call it first to set the LogFile.
        // Use a benign call (no reentry) to set the log: the attacker only reenters during the subsequent SetMinSum.
        c.SetLogFile(address(attacker));

        // instruct attacker whether to reenter on the next external call
        attacker.setShouldReenter(attackerWillReenter);

        // Perform the tested external call. We capture whether it completed (did not revert) via try/catch.
        bool ok;
        try c.SetMinSum(newVal) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: After the external call returns (either successfully or revert),
        // in the reference contract MinSum must equal newVal when the call succeeded.
        // For this test we assert the behaviour by reading the public getter c.MinSum().
        // This holds for the reference (non-reentrant) for all inputs; the mutant (which allows reentrancy)
        // can be reentered by the attacker and leave MinSum != newVal for some inputs (attackerWillReenter==true).

        // Single assertion required: if the external call succeeded, then MinSum must equal newVal.
        // If the call reverted, the reference still preserves that MinSum != newVal is impossible due to revert,
        // but we only assert the condition for successful calls to avoid false negatives when revert occurs.
        if (ok) {
            assertTrue(c.MinSum() == newVal);
        } else {
            // If the call reverted, still assert that MinSum is not changed to an unrelated value.
            // But to keep exactly one assertion path as required, we assert True on a tautology only in the revert case
            // by checking a property that holds trivially: address(c) != address(0).
            // However the test harness requires exactly one assertTrue reading c; the relevant observable is c.MinSum().
            // To satisfy the requirement while not failing on reference, we assert that when call reverted, MinSum is NOT newVal.
            // This is safe because when call reverts, state should be unchanged (MinSum remains previous value 0), so MinSum != newVal
            // for most newVal; to avoid accidental equality when newVal==0, we constrain to avoid that case.
            // Enforce newVal != 0 to keep the domain wide but exclude the ambiguous case.
            vm.assume(newVal != 0);
            assertTrue(c.MinSum() != newVal);
        }
    }
}

// Adversarial helper: when called via LogFile.AddMessage, it will (optionally) reenter c.SetMinSum
// to try to exploit the removed require(!locked_) in the mutant.
contract ReentrantLog {
    address public target;
    bool public shouldReenter;
    constructor(address _t) {
        target = _t;
        shouldReenter = false;
    }
    function setShouldReenter(bool v) public {
        shouldReenter = v;
    }

    // This function matches Log.AddMessage signature used by C. It will be called by C during SetMinSum/Put/Collect
    function AddMessage(address /*_adr*/, uint /*_val*/, string memory /*_data*/) public {
        if (shouldReenter) {
            // attempt to reenter SetMinSum with a different value to detect whether reentrancy is possible
            // We call with value 1 to try to change MinSum mid-flight in the mutant.
            try C(payable(target)).SetMinSum(1) {
                // ignore
            } catch {
                // ignore
            }
        }
    }
}

