contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: newMin is the value we set; attackerValue is ETH sent to Put when reentered
    function testFuzz_property(uint256 newMin, uint256 attackerValue) public {
        // keep domain wide but reasonable for sending ETH
        attackerValue = bound(attackerValue, 0, 1 ether);

        // Deploy a malicious Log that will reenter C.SetMinSum during the external call
        ReentrantLog attacker = new ReentrantLog(address(c), newMin / 2);

        // Register attacker as the LogFile via SetLogFile before initialization
        // call from an EOA (this test contract)
        c.SetLogFile(address(attacker));

        // Now perform SetMinSum(newMin) which in reference should finish with MinSum == newMin
        // but in mutant (without require) the attacker can reenter and change MinSum
        // We call it and then assert the invariant: after call, MinSum == newMin
        c.SetMinSum(newMin);

