import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address so the fuzzer can find any caller-specific differences
    function testFuzz_property(address caller) public {
        // keep caller in the wide admissible domain but avoid the zero address (still wide)
        vm.assume(caller != address(0));

        // Act as the fuzzed caller and invoke Initialized()
        bool ok;
        vm.startPrank(caller);
        try c.Initialized() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The universal property: after any caller invokes Initialized(), the public getter intitalized() must be true.
        // This holds for the reference contract for all callers; the mutant that sets intitalized = false will
        // cause this assertion to fail for at least some caller inputs (and thus be detected by the fuzzer).
        assertTrue(ok && c.intitalized());
    }
}

