        // bound value to reasonable ETH-sized amounts to avoid overflow in timestamp add
        value = bound(value, 0, 1 ether);
        // bound lockTime to reasonable range to avoid wrapping beyond uint and to keep within warpable ranges
        lockTime = bound(lockTime, 0, 365 days);

        // fund actor so it can send value
        vm.deal(actor, value);

        // perform Put from actor with fuzzed lockTime and value
        vm.prank(actor);
        c.Put{value: value}(lockTime);

        // Read acc for actor using public mapping getter: Acc(actor).unlockTime is accessible via Acc(actor).
        (uint unlockTime, ) = getHolder(actor);

        // The universal property: after Put, unlockTime >= block.timestamp + lockTime
        // This holds for the reference contract for all inputs, but breaks for the mutant that uses msg.value instead of _lockTime.
        assertTrue(unlockTime >= block.timestamp + lockTime);
    }

    // helper to read the Holder struct via public getter Acc(address) returns (uint unlockTime, uint balance)
    // Since the contract's mapping is declared `mapping (address => Holder) public Acc;`, the compiler generates
    // a getter with signature: function Acc(address) external view returns (uint unlockTime, uint balance);
    function getHolder(address a) internal view returns (uint,uint) {
        return c.Acc(a);
    }
}

