        vm.prank(actor);
        // call Put and ignore revert behavior; we only assert property when Put succeeds
        bool ok;
        try c.Put{value: value}(lockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call reverted, the contract's state did not change; then property regarding unlockTime holds vacuously
        // Only assert when call succeeded: then reference guarantees unlockTime >= max(prevUnlock, block.timestamp + lockTime)
        if (ok) {
